using System;
using System.DirectoryServices;
using System.Net;
using System.Net.Mail;
using System.Threading.Tasks;
using System.Collections.Concurrent;
using System.Text.RegularExpressions;

namespace EmailService
{
    public class LdapUserResolver
    {
        private readonly string _ldapPath;
        private readonly ConcurrentDictionary<string, string> _cache;
        private readonly object _lockObj = new object();

        public LdapUserResolver(string ldapPath)
        {
            _ldapPath = ldapPath;
            _cache = new ConcurrentDictionary<string, string>();
        }

        public string SanitizeLdapInput(string input)
        {
            if (string.IsNullOrWhiteSpace(input)) return string.Empty;
            // RFC 4515 escaping for LDAP search filters
            string sanitized = input
                .Replace("\\", "\\5c")
                .Replace("*", "\\2a")
                .Replace("(", "\\28")
                .Replace(")", "\\29")
                .Replace("\0", "\\00");
            return sanitized;
        }

        public string BuildSearchFilter(string username, bool useDisplayName)
        {
            if (useDisplayName)
                return $"(&(objectClass=user)(displayName={username}))";
            return $"(&(objectClass=user)(sAMAccountName={username}))";
        }

        public async Task<string> ResolveEmailAsync(string username, bool useDisplayName = false)
        {
            if (_cache.TryGetValue(username, out string cached))
                return cached;

            string sanitizedName = SanitizeLdapInput(username);
            string filter = BuildSearchFilter(sanitizedName, useDisplayName);

            return await Task.Run(() =>
            {
                using (var entry = new DirectoryEntry(_ldapPath))
                using (var searcher = new DirectorySearcher(entry))
                {
                    searcher.Filter = filter;
                    searcher.PropertiesToLoad.Add("mail");
                    var result = searcher.FindOne();
                    string email = result?.Properties["mail"]?[0]?.ToString() ?? string.Empty;
                    _cache.TryAdd(username, email);
                    return email;
                }
            });
        }
    }

    public class NotificationRequest
    {
        public string Recipient { get; set; }
        public string Subject { get; set; }
        public string Body { get; set; }
        public bool LookupByDisplayName { get; set; }
        public string[] CcRecipients { get; set; }
    }

    public class EmailDispatcher
    {
        private readonly SmtpClient _smtpClient;
        private readonly LdapUserResolver _resolver;
        private readonly string _fromAddress;
        private readonly ConcurrentQueue<NotificationRequest> _retryQueue;

        public EmailDispatcher(string smtpHost, int port, string ldapPath, string fromAddress)
        {
            _smtpClient = new SmtpClient(smtpHost, port)
            {
                EnableSsl = true,
                Credentials = new NetworkCredential("svc_email", Environment.GetEnvironmentVariable("SMTP_PASSWORD"))
            };
            _resolver = new LdapUserResolver(ldapPath);
            _fromAddress = fromAddress;
            _retryQueue = new ConcurrentQueue<NotificationRequest>();
        }

        private async Task<string[]> ResolveCcAddressesAsync(string[] ccRecipients, bool useDisplayName)
        {
            if (ccRecipients == null || ccRecipients.Length == 0)
                return Array.Empty<string>();

            var tasks = new Task<string>[ccRecipients.Length];
            for (int i = 0; i < ccRecipients.Length; i++)
            {
                tasks[i] = _resolver.ResolveEmailAsync(ccRecipients[i], useDisplayName);
            }
            return await Task.WhenAll(tasks);
        }

        public async Task<bool> SendNotificationAsync(NotificationRequest request)
        {
            try
            {
                string toEmail = await _resolver.ResolveEmailAsync(
                    request.Recipient, request.LookupByDisplayName);

                if (string.IsNullOrEmpty(toEmail))
                {
                    _retryQueue.Enqueue(request);
                    return false;
                }

                var message = new MailMessage(_fromAddress, toEmail)
                {
                    Subject = request.Subject,
                    Body = request.Body,
                    IsBodyHtml = false
                };

                string[] ccEmails = await ResolveCcAddressesAsync(
                    request.CcRecipients, request.LookupByDisplayName);
                foreach (var cc in ccEmails)
                {
                    if (!string.IsNullOrEmpty(cc))
                        message.CC.Add(cc);
                }

                await _smtpClient.SendMailAsync(message);
                return true;
            }
            catch (Exception)
            {
                _retryQueue.Enqueue(request);
                return false;
            }
        }

        public async Task ProcessRetryQueueAsync(int maxRetries = 3)
        {
            int attempts = 0;
            while (_retryQueue.TryDequeue(out var request) && attempts < maxRetries)
            {
                await SendNotificationAsync(request);
                attempts++;
            }
        }
    }

    public class BatchEmailService
    {
        private readonly EmailDispatcher _dispatcher;

        public BatchEmailService(EmailDispatcher dispatcher)
        {
            _dispatcher = dispatcher;
        }

        public async Task<int> SendBatchAsync(NotificationRequest[] requests)
        {
            int successCount = 0;
            var semaphore = new System.Threading.SemaphoreSlim(5);

            var tasks = requests.Select(async req =>
            {
                await semaphore.WaitAsync();
                try
                {
                    if (await _dispatcher.SendNotificationAsync(req))
                        System.Threading.Interlocked.Increment(ref successCount);
                }
                finally
                {
                    semaphore.Release();
                }
            });

            await Task.WhenAll(tasks);
            return successCount;
        }
    }
}
